#include <iomanip>
#include <iostream>
#include <vector>

double totalNotional(std::vector<double> positions) {
    double total = 0.0;
    for (double p : positions) {
        total += p;
    }
    return total;
}

int main() {
    const std::vector<double> positions = {250'000.0, 120'000.0, 80'000.0};
    // computed at run time, then fixed for the rest of the day
    const double orderLimit = totalNotional(positions) * 0.10;

    const std::vector<double> orders = {30'000.0, 52'500.0, 45'000.0};
    std::cout << std::fixed << std::setprecision(2);
    std::cout << "order limit: " << orderLimit << '\n';
    for (const auto& order : orders) {
        const bool ok = order <= orderLimit;
        std::cout << order << (ok ? " accepted" : " rejected") << '\n';
    }
    return 0;
}

