#include <iomanip>
#include <iostream>
#include <vector>

double averageSpread(std::vector<int> spreads) {
    int total = 0;
    for (int s : spreads) {
        total += s;
    }
    return static_cast<double>(total) / spreads.size();
}

int main() {
    const std::vector<int> spreads = {2, 3, 2, 9, 4};  // in cents, one per quote
    std::cout << std::fixed << std::setprecision(2);
    const double average = averageSpread(spreads);
    const double alertAbove = 2 * average;
    std::cout << "average: " << average << '\n';
    std::cout << "alert above: " << alertAbove << '\n';
    for (const auto& s : spreads) {
        const bool wide = s > alertAbove;
        std::cout << s << (wide ? " wide" : " ok") << '\n';
    }
    return 0;
}

