        book[kLevels + i] = bestAsk + static_cast<double>(i) * kTickSize;
    }
    std::cout << std::fixed << std::setprecision(2);
    std::cout << "book:";
    for (double level : book) {
        std::cout << ' ' << level;
    }
    std::cout << '\n';
    std::cout << orderTypeName('1') << ", " << orderTypeName('2') << ", " << orderTypeName('9') << '\n';
    return 0;
