#include <array>
#include <iomanip>
#include <iostream>

// ---- include/market.h: what every .cpp sees ----
inline constexpr int kLotSize = 100;
inline constexpr std::array<double, 4> kFeeTiers = {0.0010, 0.0007, 0.0005, 0.0003};
extern const double kRebate;  // declared here, defined in one .cpp
double feeFor(double notional, int tier);

// ---- src/fees.cpp ----
extern const double kRebate = 0.0002;

double feeFor(double notional, int tier) {
    return notional * kFeeTiers[tier] - notional * kRebate;
}

// ---- src/main.cpp ----
int main() {
    std::array<double, kFeeTiers.size()> fees{};  // a constant in every file
    const double notional = 101.25 * kLotSize;
    for (std::size_t tier = 0; tier < fees.size(); ++tier) {
        fees[tier] = feeFor(notional, static_cast<int>(tier));
    }
    std::cout << std::fixed << std::setprecision(4);
    std::cout << "notional " << notional << '\n';
    for (std::size_t tier = 0; tier < fees.size(); ++tier) {
        std::cout << "tier " << tier << ": " << fees[tier] << '\n';
    }
    return 0;
}

