#include <array>
#include <iostream>

// ---- include/limits.h ----
inline constexpr int kLotSize = 100;
inline constexpr std::array<int, 3> kMaxLotsByTier = {50, 20, 5};
extern const int kHardLimit;  // the desk's cap in shares, defined in limits.cpp
bool allowed(int shares, int tier);

// ---- src/limits.cpp ----
extern const int kHardLimit = 4'000;

bool allowed(int shares, int tier) {
    const bool wholeLots = shares % kLotSize == 0;
    const bool withinTier = shares <= kMaxLotsByTier[tier] * kLotSize;
    return wholeLots && withinTier && shares <= kHardLimit;
}

// ---- src/main.cpp ----
int main() {
    const std::array<int, 4> orders = {1'500, 1'250, 4'500, 400};
    const std::array<int, 4> tiers = {1, 0, 0, 2};
    for (std::size_t i = 0; i < orders.size(); ++i) {
        std::cout << orders[i] << " shares, tier " << tiers[i] << ": "
                  << (allowed(orders[i], tiers[i]) ? "ok" : "rejected") << '\n';
    }
    return 0;
}

