#include <iostream>
#include <string>

// FIX tag 59, how long an order stays live
enum class TimeInForce : char { Day = '0', Gtc = '1', Ioc = '3', Fok = '4' };

std::string tifField(TimeInForce tif) {
    return std::string("59=") + static_cast<char>(tif);
}

std::string describe(TimeInForce tif) {
    switch (tif) {
        case TimeInForce::Day: return "day";
        case TimeInForce::Gtc: return "good till cancel";
        case TimeInForce::Ioc: return "immediate or cancel";
        case TimeInForce::Fok: return "fill or kill";
    }
    return "?";
}

int main() {
    std::cout << tifField(TimeInForce::Day) << ' ' << describe(TimeInForce::Day) << '\n';
    std::cout << tifField(TimeInForce::Gtc) << ' ' << describe(TimeInForce::Gtc) << '\n';
    std::cout << tifField(TimeInForce::Ioc) << ' ' << describe(TimeInForce::Ioc) << '\n';
    std::cout << tifField(TimeInForce::Fok) << ' ' << describe(TimeInForce::Fok) << '\n';
    std::cout << "size " << sizeof(TimeInForce) << '\n';
    return 0;
}
